-- In draft or off a workspace's assistant stays assigned but never answers, so a visitor who writes then waits for the
-- team: the inbox lists such a conversation in the team's normal views exactly as one without an assistant
-- (src/modules/management/ai-held.ts). inbox_visitor_waiting holds each conversation where a visitor has written here
-- since the assistant last did: a message with a visitor authorship row (every customer message admitted here writes
-- one; legacy imports write none), not moved in (move_in_message_sources), above the assistant's latest revision. It is
-- derived like the inbox entries (migration 313): filled here, kept current by triggers, rebuilt after every import.
-- An entry's ai and ai_profile flags now also require that the conversation is not released to the team: released means
-- a visitor is waiting and the workspace's mode is not auto. So a mode switch alone moves no conversation whose visitor
-- the assistant answered, a teammate reply or a draft->off switch does not hide a waiting visitor again, imported history
-- never counts, and in auto the flags are exactly as before. Every 313 trigger that derives an entry is re-created with
-- the new flags; a waiting change and a mode switch re-derive only the conversations they release or hold.
CREATE TABLE inbox_visitor_waiting(conversation_id TEXT PRIMARY KEY,project_id TEXT NOT NULL);
CREATE INDEX inbox_visitor_waiting_project ON inbox_visitor_waiting(project_id);
INSERT INTO inbox_visitor_waiting(conversation_id,project_id) SELECT DISTINCT vm.conversation_id,vm.project_id FROM message_authorship va JOIN messages vm ON vm.id=va.message_id WHERE va.kind='visitor' AND NOT EXISTS(SELECT 1 FROM move_in_message_sources ims WHERE ims.message_id=vm.id) AND vm.revision>COALESCE((SELECT MAX(am.revision) FROM messages am WHERE am.conversation_id=vm.conversation_id AND am.actor_role='ai'),0) AND EXISTS(SELECT 1 FROM conversations wc WHERE wc.id=vm.conversation_id);
DROP TRIGGER inbox_conversation_added;
CREATE TRIGGER inbox_conversation_added AFTER INSERT ON conversations BEGIN
 DELETE FROM inbox_entries WHERE conversation_id=NEW.id;
 INSERT INTO inbox_entries(conversation_id,project_id,contact_id,company_id,assigned_to,group_id,status_category,priority,channel,status_id,subject,brand_id,requester_id,submitter_id,submitter_type,created_at,updated_at,ticket_version,sort_at,unresolved,counts_open,ai,ai_profile,snoozed,contact_revision,tags_key) SELECT rc.id,rc.project_id,rc.contact_id,(SELECT cc.company_id FROM contact_companies cc WHERE cc.project_id=rc.project_id AND cc.contact_id=rc.contact_id),rc.assigned_to,rc.group_id,rc.status_category,rc.priority,rc.channel,rc.status_id,rc.subject,rc.brand_id,rc.requester_id,rc.submitter_id,rc.submitter_type,rc.created_at,rc.updated_at,rc.ticket_version,coalesce((SELECT lm.created_at FROM messages lm WHERE lm.id=rc.last_message_id),rc.updated_at),rc.resolved_at IS NULL,COALESCE(rc.resolved_at,0)=0,(EXISTS(SELECT 1 FROM conversation_ai ca WHERE ca.conversation_id=rc.id AND ca.ai_id IS NOT NULL) AND NOT (EXISTS(SELECT 1 FROM inbox_visitor_waiting vw WHERE vw.conversation_id=rc.id) AND COALESCE((SELECT json_extract(ps.settings_json,'$.ai_reply_mode') FROM project_settings ps WHERE ps.project_id=rc.project_id),'auto')<>'auto')),(EXISTS(SELECT 1 FROM conversation_ai ca JOIN ai_profiles ap ON ap.id=ca.ai_id WHERE ca.conversation_id=rc.id) AND NOT (EXISTS(SELECT 1 FROM inbox_visitor_waiting vw WHERE vw.conversation_id=rc.id) AND COALESCE((SELECT json_extract(ps.settings_json,'$.ai_reply_mode') FROM project_settings ps WHERE ps.project_id=rc.project_id),'auto')<>'auto')),EXISTS(SELECT 1 FROM workflow_schedules ws WHERE ws.conversation_id=rc.id AND ws.kind='snooze' AND ws.state='pending'),(SELECT msg.revision FROM messages msg WHERE msg.conversation_id=rc.id AND msg.actor_role='contact' AND NOT EXISTS(SELECT 1 FROM move_in_message_sources ims WHERE ims.message_id=msg.id) ORDER BY msg.revision DESC LIMIT 1),(SELECT json_group_array(ct.tag_id) FROM conversation_tags ct WHERE +ct.project_id=rc.project_id AND ct.conversation_id=rc.id) FROM conversations rc WHERE rc.id=NEW.id AND (EXISTS(SELECT 1 FROM messages im WHERE im.conversation_id=rc.id) OR EXISTS(SELECT 1 FROM conversation_notes inn WHERE inn.conversation_id=rc.id)) AND NOT EXISTS(SELECT 1 FROM conversation_merges merged WHERE merged.project_id=rc.project_id AND merged.source_id=rc.id AND merged.undone_at IS NULL);
END;
