NEW.id AND (EXISTS(SELECT 1 FROM messages im WHERE im.conversation_id=rc.id) OR EXISTS(SELECT 1 FROM conversation_notes inn WHERE inn.conversation_id=rc.id)) AND NOT EXISTS(SELECT 1 FROM conversation_merges merged WHERE merged.project_id=rc.project_id AND merged.source_id=rc.id AND merged.undone_at IS NULL);
