-- A message, its authorship or its imported mark changes whether a visitor is waiting.
CREATE TRIGGER inbox_waiting_message_added AFTER INSERT ON messages BEGIN
 DELETE FROM inbox_visitor_waiting WHERE conversation_id=NEW.conversation_id AND NOT EXISTS(SELECT 1 FROM messages vm JOIN message_authorship va ON va.message_id=vm.id AND va.kind='visitor' WHERE vm.conversation_id=NEW.conversation_id AND NOT EXISTS(SELECT 1 FROM move_in_message_sources ims WHERE ims.message_id=vm.id) AND vm.revision>COALESCE((SELECT MAX(am.revision) FROM messages am WHERE am.conversation_id=NEW.conversation_id AND am.actor_role='ai'),0));
 INSERT INTO inbox_visitor_waiting(conversation_id,project_id) SELECT wc.id,wc.project_id FROM conversations wc WHERE wc.id=NEW.conversation_id AND NOT EXISTS(SELECT 1 FROM inbox_visitor_waiting known WHERE known.conversation_id=wc.id) AND EXISTS(SELECT 1 FROM messages vm JOIN message_authorship va ON va.message_id=vm.id AND va.kind='visitor' WHERE vm.conversation_id=wc.id AND NOT EXISTS(SELECT 1 FROM move_in_message_sources ims WHERE ims.message_id=vm.id) AND vm.revision>COALESCE((SELECT MAX(am.revision) FROM messages am WHERE am.conversation_id=wc.id AND am.actor_role='ai'),0));
END;
