CREATE TRIGGER inbox_waiting_conversation_moved AFTER UPDATE OF project_id ON conversations WHEN NEW.project_id IS NOT OLD.project_id BEGIN
 UPDATE inbox_visitor_waiting SET project_id=NEW.project_id WHERE conversation_id=NEW.id;
END;
CREATE TRIGGER inbox_waiting_conversation_removed AFTER DELETE ON conversations BEGIN
 DELETE FROM inbox_visitor_waiting WHERE conversation_id=OLD.id;
END;
-- A visitor starting or ending a wait re-derives the entry only where it changes a flag: an assisted conversation outside auto.
CREATE TRIGGER inbox_waiting_started AFTER INSERT ON inbox_visitor_waiting WHEN EXISTS(SELECT 1 FROM conversation_ai ca WHERE ca.conversation_id=NEW.conversation_id AND ca.ai_id IS NOT NULL) AND EXISTS(SELECT 1 FROM conversations wc WHERE wc.id=NEW.conversation_id AND COALESCE((SELECT json_extract(ms.settings_json,'$.ai_reply_mode') FROM project_settings ms WHERE ms.project_id=wc.project_id),'auto')<>'auto') BEGIN
 DELETE FROM inbox_entries WHERE conversation_id=NEW.conversation_id;
 INSERT INTO inbox_entries(conversation_id,project_id,contact_id,company_id,assigned_to,group_id,status_category,priority,channel,status_id,subject,brand_id,requester_id,submitter_id,submitter_type,created_at,updated_at,ticket_version,sort_at,unresolved,counts_open,ai,ai_profile,snoozed,contact_revision,tags_key) SELECT rc.id,rc.project_id,rc.contact_id,(SELECT cc.company_id FROM contact_companies cc WHERE cc.project_id=rc.project_id AND cc.contact_id=rc.contact_id),rc.assigned_to,rc.group_id,rc.status_category,rc.priority,rc.channel,rc.status_id,rc.subject,rc.brand_id,rc.requester_id,rc.submitter_id,rc.submitter_type,rc.created_at,rc.updated_at,rc.ticket_version,coalesce((SELECT lm.created_at FROM messages lm WHERE lm.id=rc.last_message_id),rc.updated_at),rc.resolved_at IS NULL,COALESCE(rc.resolved_at,0)=0,(EXISTS(SELECT 1 FROM conversation_ai ca WHERE ca.conversation_id=rc.id AND ca.ai_id IS NOT NULL) AND NOT (EXISTS(SELECT 1 FROM inbox_visitor_waiting vw WHERE vw.conversation_id=rc.id) AND COALESCE((SELECT json_extract(ps.settings_json,'$.ai_reply_mode') FROM project_settings ps WHERE ps.project_id=rc.project_id),'auto')<>'auto')),(EXISTS(SELECT 1 FROM conversation_ai ca JOIN ai_profiles ap ON ap.id=ca.ai_id WHERE ca.conversation_id=rc.id) AND NOT (EXISTS(SELECT 1 FROM inbox_visitor_waiting vw WHERE vw.conversation_id=rc.id) AND COALESCE((SELECT json_extract(ps.settings_json,'$.ai_reply_mode') FROM project_settings ps WHERE ps.project_id=rc.project_id),'auto')<>'auto')),EXISTS(SELECT 1 FROM workflow_schedules ws WHERE ws.conversation_id=rc.id AND ws.kind='snooze' AND ws.state='pending'),(SELECT msg.revision FROM messages msg WHERE msg.conversation_id=rc.id AND msg.actor_role='contact' AND NOT EXISTS(SELECT 1 FROM move_in_message_sources ims WHERE ims.message_id=msg.id) ORDER BY msg.revision DESC LIMIT 1),(SELECT json_group_array(ct.tag_id) FROM conversation_tags ct WHERE +ct.project_id=rc.project_id AND ct.conversation_id=rc.id) FROM conversations rc WHERE rc.id=NEW.conversation_id AND (EXISTS(SELECT 1 FROM messages im WHERE im.conversation_id=rc.id) OR EXISTS(SELECT 1 FROM conversation_notes inn WHERE inn.conversation_id=rc.id)) AND NOT EXISTS(SELECT 1 FROM conversation_merges merged WHERE merged.project_id=rc.project_id AND merged.source_id=rc.id AND merged.undone_at IS NULL);
END;
CREATE TRIGGER inbox_waiting_ended AFTER DELETE ON inbox_visitor_waiting WHEN EXISTS(SELECT 1 FROM conversation_ai ca WHERE ca.conversation_id=OLD.conversation_id AND ca.ai_id IS NOT NULL) AND EXISTS(SELECT 1 FROM conversations wc WHERE wc.id=OLD.conversation_id AND COALESCE((SELECT json_extract(ms.settings_json,'$.ai_reply_mode') FROM project_settings ms WHERE ms.project_id=wc.project_id),'auto')<>'auto') BEGIN
 DELETE FROM inbox_entries WHERE conversation_id=OLD.conversation_id;
 INSERT INTO inbox_entries(conversation_id,project_id,contact_id,company_id,assigned_to,group_id,status_category,priority,channel,status_id,subject,brand_id,requester_id,submitter_id,submitter_type,created_at,updated_at,ticket_version,sort_at,unresolved,counts_open,ai,ai_profile,snoozed,contact_revision,tags_key) SELECT rc.id,rc.project_id,rc.contact_id,(SELECT cc.company_id FROM contact_companies cc WHERE cc.project_id=rc.project_id AND cc.contact_id=rc.contact_id),rc.assigned_to,rc.group_id,rc.status_category,rc.priority,rc.channel,rc.status_id,rc.subject,rc.brand_id,rc.requester_id,rc.submitter_id,rc.submitter_type,rc.created_at,rc.updated_at,rc.ticket_version,coalesce((SELECT lm.created_at FROM messages lm WHERE lm.id=rc.last_message_id),rc.updated_at),rc.resolved_at IS NULL,COALESCE(rc.resolved_at,0)=0,(EXISTS(SELECT 1 FROM conversation_ai ca WHERE ca.conversation_id=rc.id AND ca.ai_id IS NOT NULL) AND NOT (EXISTS(SELECT 1 FROM inbox_visitor_waiting vw WHERE vw.conversation_id=rc.id) AND COALESCE((SELECT json_extract(ps.settings_json,'$.ai_reply_mode') FROM project_settings ps WHERE ps.project_id=rc.project_id),'auto')<>'auto')),(EXISTS(SELECT 1 FROM conversation_ai ca JOIN ai_profiles ap ON ap.id=ca.ai_id WHERE ca.conversation_id=rc.id) AND NOT (EXISTS(SELECT 1 FROM inbox_visitor_waiting vw WHERE vw.conversation_id=rc.id) AND COALESCE((SELECT json_extract(ps.settings_json,'$.ai_reply_mode') FROM project_settings ps WHERE ps.project_id=rc.project_id),'auto')<>'auto')),EXISTS(SELECT 1 FROM workflow_schedules ws WHERE ws.conversation_id=rc.id AND ws.kind='snooze' AND ws.state='pending'),(SELECT msg.revision FROM messages msg WHERE msg.conversation_id=rc.id AND msg.actor_role='contact' AND NOT EXISTS(SELECT 1 FROM move_in_message_sources ims WHERE ims.message_id=msg.id) ORDER BY msg.revision DESC LIMIT 1),(SELECT json_group_array(ct.tag_id) FROM conversation_tags ct WHERE +ct.project_id=rc.project_id AND ct.conversation_id=rc.id) FROM conversations rc WHERE rc.id=OLD.conversation_id AND (EXISTS(SELECT 1 FROM messages im WHERE im.conversation_id=rc.id) OR EXISTS(SELECT 1 FROM conversation_notes inn WHERE inn.conversation_id=rc.id)) AND NOT EXISTS(SELECT 1 FROM conversation_merges merged WHERE merged.project_id=rc.project_id AND merged.source_id=rc.id AND merged.undone_at IS NULL);
END;
-- A switch into or out of auto re-derives the workspace's assisted conversations whose visitor is waiting; draft<->off changes nothing.
CREATE TRIGGER inbox_mode_added AFTER INSERT ON project_settings WHEN NOT COALESCE(json_extract(NEW.settings_json,'$.ai_reply_mode'),'auto')='auto' BEGIN
 DELETE FROM inbox_entries WHERE conversation_id IN (SELECT vw.conversation_id FROM inbox_visitor_waiting vw WHERE vw.project_id=NEW.project_id AND EXISTS(SELECT 1 FROM conversation_ai ca WHERE ca.conversation_id=vw.conversation_id AND ca.ai_id IS NOT NULL));
 INSERT INTO inbox_entries(conversation_id,project_id,contact_id,company_id,assigned_to,group_id,status_category,priority,channel,status_id,subject,brand_id,requester_id,submitter_id,submitter_type,created_at,updated_at,ticket_version,sort_at,unresolved,counts_open,ai,ai_profile,snoozed,contact_revision,tags_key) SELECT rc.id,rc.project_id,rc.contact_id,(SELECT cc.company_id FROM contact_companies cc WHERE cc.project_id=rc.project_id AND cc.contact_id=rc.contact_id),rc.assigned_to,rc.group_id,rc.status_category,rc.priority,rc.channel,rc.status_id,rc.subject,rc.brand_id,rc.requester_id,rc.submitter_id,rc.submitter_type,rc.created_at,rc.updated_at,rc.ticket_version,coalesce((SELECT lm.created_at FROM messages lm WHERE lm.id=rc.last_message_id),rc.updated_at),rc.resolved_at IS NULL,COALESCE(rc.resolved_at,0)=0,(EXISTS(SELECT 1 FROM conversation_ai ca WHERE ca.conversation_id=rc.id AND ca.ai_id IS NOT NULL) AND NOT (EXISTS(SELECT 1 FROM inbox_visitor_waiting vw WHERE vw.conversation_id=rc.id) AND COALESCE((SELECT json_extract(ps.settings_json,'$.ai_reply_mode') FROM project_settings ps WHERE ps.project_id=rc.project_id),'auto')<>'auto')),(EXISTS(SELECT 1 FROM conversation_ai ca JOIN ai_profiles ap ON ap.id=ca.ai_id WHERE ca.conversation_id=rc.id) AND NOT (EXISTS(SELECT 1 FROM inbox_visitor_waiting vw WHERE vw.conversation_id=rc.id) AND COALESCE((SELECT json_extract(ps.settings_json,'$.ai_reply_mode') FROM project_settings ps WHERE ps.project_id=rc.project_id),'auto')<>'auto')),EXISTS(SELECT 1 FROM workflow_schedules ws WHERE ws.conversation_id=rc.id AND ws.kind='snooze' AND ws.state='pending'),(SELECT msg.revision FROM messages msg WHERE msg.conversation_id=rc.id AND msg.actor_role='contact' AND NOT EXISTS(SELECT 1 FROM move_in_message_sources ims WHERE ims.message_id=msg.id) ORDER BY msg.revision DESC LIMIT 1),(SELECT json_group_array(ct.tag_id) FROM conversation_tags ct WHERE +ct.project_id=rc.project_id AND ct.conversation_id=rc.id) FROM conversations rc WHERE rc.id IN (SELECT vw.conversation_id FROM inbox_visitor_waiting vw WHERE vw.project_id=NEW.project_id AND EXISTS(SELECT 1 FROM conversation_ai ca WHERE ca.conversation_id=vw.conversation_id AND ca.ai_id IS NOT NULL)) AND (EXISTS(SELECT 1 FROM messages im WHERE im.conversation_id=rc.id) OR EXISTS(SELECT 1 FROM conversation_notes inn WHERE inn.conversation_id=rc.id)) AND NOT EXISTS(SELECT 1 FROM conversation_merges merged WHERE merged.project_id=rc.project_id AND merged.source_id=rc.id AND merged.undone_at IS NULL);
END;
CREATE TRIGGER inbox_mode_changed AFTER UPDATE OF project_id,settings_json ON project_settings WHEN NEW.project_id IS NOT OLD.project_id OR (COALESCE(json_extract(NEW.settings_json,'$.ai_reply_mode'),'auto')='auto') IS NOT (COALESCE(json_extract(OLD.settings_json,'$.ai_reply_mode'),'auto')='auto') BEGIN
 DELETE FROM inbox_entries WHERE conversation_id IN (SELECT vw.conversation_id FROM inbox_visitor_waiting vw WHERE vw.project_id=OLD.project_id AND EXISTS(SELECT 1 FROM conversation_ai ca WHERE ca.conversation_id=vw.conversation_id AND ca.ai_id IS NOT NULL));
 INSERT INTO inbox_entries(conversation_id,project_id,contact_id,company_id,assigned_to,group_id,status_category,priority,channel,status_id,subject,brand_id,requester_id,submitter_id,submitter_type,created_at,updated_at,ticket_version,sort_at,unresolved,counts_open,ai,ai_profile,snoozed,contact_revision,tags_key) SELECT rc.id,rc.project_id,rc.contact_id,(SELECT cc.company_id FROM contact_companies cc WHERE cc.project_id=rc.project_id AND cc.contact_id=rc.contact_id),rc.assigned_to,rc.group_id,rc.status_category,rc.priority,rc.channel,rc.status_id,rc.subject,rc.brand_id,rc.requester_id,rc.submitter_id,rc.submitter_type,rc.created_at,rc.updated_at,rc.ticket_version,coalesce((SELECT lm.created_at FROM messages lm WHERE lm.id=rc.last_message_id),rc.updated_at),rc.resolved_at IS NULL,COALESCE(rc.resolved_at,0)=0,(EXISTS(SELECT 1 FROM conversation_ai ca WHERE ca.conversation_id=rc.id AND ca.ai_id IS NOT NULL) AND NOT (EXISTS(SELECT 1 FROM inbox_visitor_waiting vw WHERE vw.conversation_id=rc.id) AND COALESCE((SELECT json_extract(ps.settings_json,'$.ai_reply_mode') FROM project_settings ps WHERE ps.project_id=rc.project_id),'auto')<>'auto')),(EXISTS(SELECT 1 FROM conversation_ai ca JOIN ai_profiles ap ON ap.id=ca.ai_id WHERE ca.conversation_id=rc.id) AND NOT (EXISTS(SELECT 1 FROM inbox_visitor_waiting vw WHERE vw.conversation_id=rc.id) AND COALESCE((SELECT json_extract(ps.settings_json,'$.ai_reply_mode') FROM project_settings ps WHERE ps.project_id=rc.project_id),'auto')<>'auto')),EXISTS(SELECT 1 FROM workflow_schedules ws WHERE ws.conversation_id=rc.id AND ws.kind='snooze' AND ws.state='pending'),(SELECT msg.revision FROM messages msg WHERE msg.conversation_id=rc.id AND msg.actor_role='contact' AND NOT EXISTS(SELECT 1 FROM move_in_message_sources ims WHERE ims.message_id=msg.id) ORDER BY msg.revision DESC LIMIT 1),(SELECT json_group_array(ct.tag_id) FROM conversation_tags ct WHERE +ct.project_id=rc.project_id AND ct.conversation_id=rc.id) FROM conversations rc WHERE rc.id IN (SELECT vw.conversation_id FROM inbox_visitor_waiting vw WHERE vw.project_id=OLD.project_id AND EXISTS(SELECT 1 FROM conversation_ai ca WHERE ca.conversation_id=vw.conversation_id AND ca.ai_id IS NOT NULL)) AND (EXISTS(SELECT 1 FROM messages im WHERE im.conversation_id=rc.id) OR EXISTS(SELECT 1 FROM conversation_notes inn WHERE inn.conversation_id=rc.id)) AND NOT EXISTS(SELECT 1 FROM conversation_merges merged WHERE merged.project_id=rc.project_id AND merged.source_id=rc.id AND merged.undone_at IS NULL);
 DELETE FROM inbox_entries WHERE conversation_id IN (SELECT vw.conversation_id FROM inbox_visitor_waiting vw WHERE vw.project_id=NEW.project_id AND EXISTS(SELECT 1 FROM conversation_ai ca WHERE ca.conversation_id=vw.conversation_id AND ca.ai_id IS NOT NULL));
 INSERT INTO inbox_entries(conversation_id,project_id,contact_id,company_id,assigned_to,group_id,status_category,priority,channel,status_id,subject,brand_id,requester_id,submitter_id,submitter_type,created_at,updated_at,ticket_version,sort_at,unresolved,counts_open,ai,ai_profile,snoozed,contact_revision,tags_key) SELECT rc.id,rc.project_id,rc.contact_id,(SELECT cc.company_id FROM contact_companies cc WHERE cc.project_id=rc.project_id AND cc.contact_id=rc.contact_id),rc.assigned_to,rc.group_id,rc.status_category,rc.priority,rc.channel,rc.status_id,rc.subject,rc.brand_id,rc.requester_id,rc.submitter_id,rc.submitter_type,rc.created_at,rc.updated_at,rc.ticket_version,coalesce((SELECT lm.created_at FROM messages lm WHERE lm.id=rc.last_message_id),rc.updated_at),rc.resolved_at IS NULL,COALESCE(rc.resolved_at,0)=0,(EXISTS(SELECT 1 FROM conversation_ai ca WHERE ca.conversation_id=rc.id AND ca.ai_id IS NOT NULL) AND NOT (EXISTS(SELECT 1 FROM inbox_visitor_waiting vw WHERE vw.conversation_id=rc.id) AND COALESCE((SELECT json_extract(ps.settings_json,'$.ai_reply_mode') FROM project_settings ps WHERE ps.project_id=rc.project_id),'auto')<>'auto')),(EXISTS(SELECT 1 FROM conversation_ai ca JOIN ai_profiles ap ON ap.id=ca.ai_id WHERE ca.conversation_id=rc.id) AND NOT (EXISTS(SELECT 1 FROM inbox_visitor_waiting vw WHERE vw.conversation_id=rc.id) AND COALESCE((SELECT json_extract(ps.settings_json,'$.ai_reply_mode') FROM project_settings ps WHERE ps.project_id=rc.project_id),'auto')<>'auto')),EXISTS(SELECT 1 FROM workflow_schedules ws WHERE ws.conversation_id=rc.id AND ws.kind='snooze' AND ws.state='pending'),(SELECT msg.revision FROM messages msg WHERE msg.conversation_id=rc.id AND msg.actor_role='contact' AND NOT EXISTS(SELECT 1 FROM move_in_message_sources ims WHERE ims.message_id=msg.id) ORDER BY msg.revision DESC LIMIT 1),(SELECT json_group_array(ct.tag_id) FROM conversation_tags ct WHERE +ct.project_id=rc.project_id AND ct.conversation_id=rc.id) FROM conversations rc WHERE rc.id IN (SELECT vw.conversation_id FROM inbox_visitor_waiting vw WHERE vw.project_id=NEW.project_id AND EXISTS(SELECT 1 FROM conversation_ai ca WHERE ca.conversation_id=vw.conversation_id AND ca.ai_id IS NOT NULL)) AND (EXISTS(SELECT 1 FROM messages im WHERE im.conversation_id=rc.id) OR EXISTS(SELECT 1 FROM conversation_notes inn WHERE inn.conversation_id=rc.id)) AND NOT EXISTS(SELECT 1 FROM conversation_merges merged WHERE merged.project_id=rc.project_id AND merged.source_id=rc.id AND merged.undone_at IS NULL);
END;
CREATE TRIGGER inbox_mode_removed AFTER DELETE ON project_settings WHEN NOT COALESCE(json_extract(OLD.settings_json,'$.ai_reply_mode'),'auto')='auto' BEGIN
 DELETE FROM inbox_entries WHERE conversation_id IN (SELECT vw.conversation_id FROM inbox_visitor_waiting vw WHERE vw.project_id=OLD.project_id AND EXISTS(SELECT 1 FROM conversation_ai ca WHERE ca.conversation_id=vw.conversation_id AND ca.ai_id IS NOT NULL));
